<script setup>
import { computed } from 'vue';
import { Head, useForm } from '@inertiajs/vue3';
import AdminLayout from '../../../Layouts/AdminLayout.vue';
import PageHeader from '../../../Components/Ui/PageHeader.vue';

defineOptions({ layout: AdminLayout });
const props = defineProps({ table:{type:Object,required:true}, zones:{type:Array,default:()=>[]}, canManageZones:Boolean, urls:{type:Object,required:true} });
const editing = computed(() => Boolean(props.table.id));
const form = useForm({ number:props.table.number, name:props.table.name, capacity:props.table.capacity, zone_lookup_id:props.table.zoneId??'', status:props.table.status, active:Boolean(props.table.active) });
const statusOptions=[{value:'available',label:'متاحة للخدمة',icon:'bi-check-circle',help:'تظهر للجرسون ويمكن فتح طلب عليها'},{value:'reserved',label:'محجوزة',icon:'bi-calendar-check',help:'محجوزة لضيف أو موعد قريب'},{value:'out_of_service',label:'خارج الخدمة',icon:'bi-tools',help:'تنظيف أو صيانة ولا تستقبل طلباً'},{value:'occupied',label:'مشغولة',icon:'bi-people',help:'استخدمها فقط عند تصحيح حالة فعلية'}];
function submit(){editing.value?form.put(props.urls.submit,{preserveScroll:true}):form.post(props.urls.submit,{preserveScroll:true})}
</script>
<template>
<Head :title="editing?`تعديل طاولة ${table.number}`:'طاولة جديدة'"/>
<PageHeader :title="editing?`تعديل طاولة ${table.number}`:'إضافة طاولة'" icon="bi-grid-3x3-gap-fill"  :crumbs="[{label:'لوحة الصالة',url:urls.index}]"/>
<form class="table-form" @submit.prevent="submit">
  <section class="card main-card"><header><div><small>تعريف الطاولة</small><h2>ما الذي يراه الجرسون؟</h2></div><span class="preview-number">{{form.number||'—'}}</span></header>
    <div class="fields"><label><span>رقم الطاولة *</span><input v-model="form.number" class="form-control number" maxlength="16" required autofocus placeholder="مثال: 12"><small>يمكن تكرار الرقم في فرع آخر.</small><em v-if="form.errors.number">{{form.errors.number}}</em></label><label><span>اسم إضافي</span><input v-model="form.name" class="form-control" maxlength="255" placeholder="مثال: قرب النافذة"><em v-if="form.errors.name">{{form.errors.name}}</em></label><label><span>السعة *</span><div class="capacity"><button type="button" @click="form.capacity=Math.max(1,Number(form.capacity)-1)">−</button><input v-model="form.capacity" type="number" min="1" max="50" required><button type="button" @click="form.capacity=Math.min(50,Number(form.capacity)+1)">+</button></div><em v-if="form.errors.capacity">{{form.errors.capacity}}</em></label><label><span>القسم</span><select v-model="form.zone_lookup_id" class="form-select"><option value="">بدون قسم</option><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{zone.label}}</option></select><a v-if="canManageZones" :href="urls.zones">إدارة أقسام الصالة</a><em v-if="form.errors.zone_lookup_id">{{form.errors.zone_lookup_id}}</em></label></div>
  </section>
  <section class="card"><header class="section-head"><div><small>الحالة</small><h2>هل تستقبل طلباً الآن؟</h2></div><label class="active-switch"><input v-model="form.active" type="checkbox"><span></span><b>{{form.active?'نشطة':'مخفية'}}</b></label></header><div class="status-grid"><button v-for="status in statusOptions" :key="status.value" type="button" :class="{selected:form.status===status.value}" @click="form.status=status.value"><i class="bi" :class="status.icon"></i><span><strong>{{status.label}}</strong><small>{{status.help}}</small></span><i class="bi check" :class="form.status===status.value?'bi-check-circle-fill':'bi-circle'"></i></button></div><em v-if="form.errors.status" class="error">{{form.errors.status}}</em></section>
  <footer><a :href="urls.index" class="btn btn-light">إلغاء</a><button class="btn btn-primary" :disabled="form.processing"><i class="bi bi-check2-circle"></i>{{form.processing?'جارٍ الحفظ…':editing?'حفظ التعديلات':'إضافة إلى الصالة'}}</button></footer>
</form>
</template>
<style scoped>
